css:
.logo-cell {
    padding-right: 30px !important;
}

.address-cell {
    padding-left: 30px !important;
}

.hardcoded-letterhead {
    width: 100%;
    margin: 0 0 10px 0;
    padding: 0;
}

.hardcoded-letterhead img {
    max-width: 100%;
    height: auto;
}

html:
{% set vat_rate = 0 %}
{% if doc.taxes and doc.taxes|length > 0 %}
    {% set vat_rate = frappe.utils.flt(doc.taxes[0].rate) %}
{% endif %}

<style>
    @page {
        size: A4;
        margin: 10mm 12mm 12mm 12mm;
    }

    * {
        box-sizing: border-box;
    }

    body,
    .print-format {
        font-family: Arial, Helvetica, sans-serif;
        font-size: 10px;
        color: #333;
        line-height: 1.35;
    }

    .invoice-container {
        width: 100%;
        min-height: 270mm;
        position: relative;
    }

    /* Letterhead */

    /*.letterhead-table {*/
    /*    width: 100%;*/
    /*    border-collapse: collapse;*/
    /*    margin-bottom: 10px;*/
    /*}*/

    /*.letterhead-table td {*/
    /*    border: none !important;*/
    /*    padding: 0;*/
    /*    vertical-align: top;*/
    /*}*/

    /*.logo-cell {*/
    /*    width: 50%;*/
    /*    text-align: left;*/
    /*}*/

    /*.address-cell {*/
    /*    width: 50%;*/
    /*    text-align: right;*/
    /*}*/

    /*.logo-image {*/
    /*    width: 285px;*/
    /*    max-height: 85px;*/
    /*    object-fit: contain;*/
    /*    object-position: left top;*/
    /*}*/

    /*.address-image {*/
    /*    width: 260px;*/
    /*    max-height: 90px;*/
    /*    object-fit: contain;*/
    /*    object-position: right top;*/
    /*}*/

    /* Title */

    .title-row {
        display: flex;
        align-items: center;
        margin: 8px 0 18px;
    }

    .title-line {
        flex: 1;
        height: 1px;
        background: #c5c5c5;
    }

    .invoice-title {
        padding: 0 16px;
        margin: 0;
        font-size: 20px;
        font-weight: 500;
        color: #222;
        white-space: nowrap;
    }

    /* Customer and invoice information */

    .information-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 18px;
    }

    .information-table td {
        border: none !important;
        vertical-align: top;
        padding: 0;
    }

    .customer-section {
        width: 55%;
        padding-top: 50px !important;
    }

    .invoice-info-section {
        width: 45%;
    }

    .section-label {
        color: #777;
        font-size: 11px;
        margin-bottom: 2px;
    }

    .customer-name {
        font-size: 12px;
        font-weight: bold;
        color: #333;
        margin-bottom: 2px;
    }

    .customer-address {
        font-size: 10px;
        line-height: 1.4;
        color: #444;
    }

    .invoice-details {
        width: 100%;
        border-collapse: collapse;
        font-size: 10px;
    }

    .invoice-details td {
        border: 1px solid #222 !important;
        padding: 5px 10px;
        height: 26px;
    }

    .invoice-details .detail-label {
        width: 38%;
        background: #909090;
        color: white;
    }

    .invoice-details .detail-value {
        width: 62%;
        color: #222;
    }

    /* Item table */

    .item-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
        margin-bottom: 20px;
        border: 1px solid #111;
    }

    .item-table th {
        background: #929292;
        color: white;
        border: 1px solid #111;
        padding: 7px 6px;
        font-weight: normal;
        font-size: 10px;
        text-align: center;
    }

    .item-table td {
        padding: 8px 6px;
        vertical-align: top;
        border-left: none;
        border-right: none;
        border-top: none;
        border-bottom: none;
        font-size: 9.5px;
    }

    .item-table tbody tr:last-child td {
        padding-bottom: 12px;
    }

    .col-number {
        width: 8%;
        text-align: center;
    }

    .col-description {
        width: 36%;
        text-align: left;
    }

    .col-qty {
        width: 9%;
        text-align: center;
    }

    .col-rate {
        width: 13%;
        text-align: right;
    }

    .col-tax-rate {
        width: 9%;
        text-align: center;
    }

    .col-tax {
        width: 12%;
        text-align: right;
    }

    .col-amount {
        width: 13%;
        text-align: right;
    }

    .item-name {
        font-weight: 500;
        color: #222;
        margin-bottom: 2px;
    }

    .item-description {
        color: #555;
        line-height: 1.4;
        word-break: break-word;
    }

    /* Amount and totals */

    .summary-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 6px;
    }

    .summary-table td {
        border: none !important;
        padding: 0;
        vertical-align: top;
    }

    .amount-words-section {
        width: 67%;
        padding-top: 6px !important;
        padding-right: 20px !important;
        font-size: 10px;
    }

    .totals-section {
        width: 33%;
    }

    .amount-words-label {
        color: #555;
    }

    .amount-words-value {
        font-weight: bold;
        color: #333;
    }

    .totals-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10px;
    }

    .totals-table td {
        border: none !important;
        padding: 7px 5px;
        vertical-align: top;
    }

    .totals-label {
        width: 68%;
        text-align: right;
        padding-right: 12px !important;
    }

    .totals-value {
        width: 32%;
        text-align: right;
        white-space: nowrap;
    }

    .grand-total-row td {
        border-top: 2px solid #222 !important;
        padding-top: 8px;
        font-weight: bold;
    }

    .grand-total-amount {
        font-size: 12px;
        font-weight: bold;
    }

    /* Terms */

    .terms-section {
        margin-top: 28px;
        font-size: 8px;
        color: #444;
        page-break-inside: avoid;
    }

    .terms-title {
        font-size: 11px;
        color: #777;
        margin-bottom: 7px;
    }

    .terms-content {
        line-height: 1.45;
    }

    .thank-you {
        margin-top: 14px;
    }

    .signature {
        margin-top: 14px;
    }

    /* Page breaking */

    .item-table tr {
        page-break-inside: avoid;
    }

    .summary-table,
    .terms-section {
        page-break-inside: avoid;
    }

    @media print {
        body,
        .print-format {
            margin: 0;
            padding: 0;
        }

        .invoice-container {
            width: 100%;
        }
    }
</style>

<div class="invoice-container">

    <!-- Letterhead -->
<!--letterHeadfromImageAddedInthe-->
    <!--<table class="letterhead-table">-->
    <!--    <tr>-->
    <!--        <td class="logo-cell">-->
    <!--            <img-->
    <!--                src="/private/files/arabscale_logo.png"-->
    <!--                class="logo-image"-->
    <!--                alt="Arab Scale Trading"-->
    <!--            >-->
    <!--        </td>-->

    <!--        <td class="address-cell">-->
    <!--            <img-->
    <!--                src="/private/files/arabscale_address.png"-->
    <!--                class="address-image"-->
    <!--                alt="Company Address"-->
    <!--            >-->
    <!--        </td>-->
    <!--    </tr>-->
    <!--</table>-->
    {% set fixed_letterhead = letter_head if not no_letterhead else '' %}

{% if fixed_letterhead %}
    <div class="hardcoded-letterhead">
        {{ fixed_letterhead }}
    </div>
{% endif %}
    
    <!-- Letterhead -->


    <!-- Invoice title -->
    <div class="title-row">
        <div class="title-line"></div>

        <h1 class="invoice-title">
            {% if doc.is_return %}
                {{ _("Credit Note") }}
            {% else %}
                {{ _("Tax Invoice") }}
            {% endif %}
        </h1>

        <div class="title-line"></div>
    </div>

    <!-- Customer and invoice information -->
    <table class="information-table">
        <tr>
            <td class="customer-section">
                <div class="section-label">{{ _("Bill To") }}</div>

                <div class="customer-name">
                    {{ doc.customer_name or doc.customer }}
                </div>

                <div class="customer-address">
                    {% if doc.address_display %}
                        {{ doc.address_display }}
                    {% elif doc.customer_address %}
                        {{ doc.customer_address }}
                    {% endif %}
                </div>

                {% if doc.tax_id %}
                    <div style="margin-top: 4px;">
                        <strong>{{ _("Tax ID") }}:</strong> {{ doc.tax_id }}
                    </div>
                {% endif %}
            </td>

            <td class="invoice-info-section">
                <table class="invoice-details">
                    <tr>
                        <td class="detail-label">{{ _("Invoice") }} #</td>
                        <td class="detail-value">{{ doc.name }}</td>
                    </tr>

                    <tr>
                        <td class="detail-label">{{ _("Invoice Date") }}</td>
                        <td class="detail-value">
                            {{ frappe.utils.formatdate(doc.posting_date, "dd MMM yyyy") }}
                        </td>
                    </tr>

                    <tr>
                        <td class="detail-label">{{ _("Terms") }}</td>
                        <td class="detail-value">
                            {{ doc.payment_terms_template or doc.terms or "" }}
                        </td>
                    </tr>

                    <tr>
                        <td class="detail-label">{{ _("Purchase Order") }}#</td>
                        <td class="detail-value">
                            {{ doc.po_no or "" }}
                        </td>
                    </tr>

                    <tr>
                        <td class="detail-label">{{ _("Sales Person") }}</td>
                        <td class="detail-value">
                            {% if doc.sales_team and doc.sales_team|length > 0 %}
                                {{ doc.sales_team[0].sales_person }}
                            {% else %}
                                {{ doc.sales_partner or "" }}
                            {% endif %}
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <!-- Item table -->
    <table class="item-table">
        <thead>
            <tr>
                <th class="col-number">{{ _("Sr No") }}</th>
                <th class="col-description">{{ _("Item Description") }}</th>
                <th class="col-qty">{{ _("Qty") }}</th>
                <th class="col-rate">{{ _("Rate") }}</th>
                <th class="col-tax-rate">{{ _("Tax") }}%</th>
                <th class="col-tax">{{ _("Tax") }}</th>
                <th class="col-amount">{{ _("Amount") }}</th>
            </tr>
        </thead>

        <tbody>
            {% for item in doc.items %}

                {% set taxable_amount = frappe.utils.flt(item.net_amount) %}
                {% set line_tax = taxable_amount * vat_rate / 100 %}
                {% set amount_with_tax = taxable_amount + line_tax %}

                <tr>
                    <td class="col-number">
                        {{ loop.index }}
                    </td>

                    <td class="col-description">
                        <div class="item-name">
                            {{ _(item.item_name) if item.item_name else item.item_code }}
                        </div>

                        {% if item.description %}
                            <div class="item-description">
                                {{ _(item.description) }}
                            </div>
                        {% endif %}

                        {% if item.serial_no %}
                            <div class="item-description">
                                {{ _("Serial No") }}# {{ item.serial_no }}
                            </div>
                        {% endif %}

                        {% if item.batch_no %}
                            <div class="item-description">
                                {{ _("Batch") }}# {{ item.batch_no }}
                            </div>
                        {% endif %}
                    </td>

                    <td class="col-qty">
                        {{ frappe.utils.fmt_money(item.qty, precision=2) }}
                        {% if item.uom %}
                            <br>
                            <span style="font-size: 8px;">{{ _(item.uom) }}</span>
                        {% endif %}
                    </td>

                    <td class="col-rate">
                        {{ frappe.utils.fmt_money(item.net_rate, precision=2) }}
                    </td>

                    <td class="col-tax-rate">
                        {{ frappe.utils.fmt_money(vat_rate, precision=0) }}
                    </td>

                    <td class="col-tax">
                        {{ frappe.utils.fmt_money(line_tax, precision=2) }}
                    </td>

                    <td class="col-amount">
                        {{ frappe.utils.fmt_money(amount_with_tax, precision=2) }}
                    </td>
                </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- Amount in words and totals -->
    <table class="summary-table">
        <tr>
            <td class="amount-words-section">
                <span class="amount-words-label">{{ _("In Words") }} :</span>

                <span class="amount-words-value">
                    {{ frappe.utils.money_in_words((doc.rounded_total if doc.get('rounded_total') is not none and not doc.is_rounded_total_disabled() else doc.grand_total)|abs, doc.currency) }}
                </span>
            </td>

            <td class="totals-section">
                <table class="totals-table">
                    <tr>
                        <td class="totals-label">
                            {{ _("Subtotal (Taxable Amount)") }} {{ doc.currency }}
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.net_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                    <tr>
                        <td class="totals-label">{{ _("Discount") }}</td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.discount_amount or 0,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                    <tr>
                        <td class="totals-label">
                            {{ _("VAT") }} ({{ frappe.utils.fmt_money(vat_rate, precision=0) }}%):
                            {{ doc.currency }}
                        </td>

                        <td class="totals-value">
                            {{ frappe.utils.fmt_money(
                                doc.total_taxes_and_charges or 0,
                                precision=2
                            ) }}
                        </td>
                    </tr>

                    <tr class="grand-total-row">
                        <td class="totals-label">
                            {{ _("Total (Incl. VAT)") }}<br>
                            {{ doc.currency }}
                        </td>

                        <td class="totals-value grand-total-amount">
                            {{ doc.currency }}
                            {{ frappe.utils.fmt_money(
                                doc.grand_total,
                                precision=2
                            ) }}
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>

    <!-- Terms and Conditions -->
    <div class="terms-section">
        <div class="terms-title">{{ _("Terms & Conditions") }}</div>

        <div class="terms-content">
            {% if doc.terms %}
                {{ doc.terms }}
            {% else %}
                <div>{{ _("Payment: Cash / Cheque against delivery.") }}</div>
                <div>{{ _("Delivery: Ex-stock (subject to prior sale).") }}</div>
                <div>
                    {{ _("Warranty: 12 Months from the date of Invoice (against any manufacturing defect)") }}
                </div>
            {% endif %}
        </div>

        <div class="thank-you">
            {{ _("We take this opportunity to thank you for your enquiry, if you have any query please feel free to contact us.") }}
        </div>

        <div class="signature">
            {{ _("For") }} {{ doc.company }},
        </div>
    </div>

</div>
{% if footer and not no_letterhead %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}

<style id="retail-print-language-layout">
[dir="rtl"] .print-format { text-align: right; }
[dir="rtl"] .print-format .heading-section, [dir="rtl"] .print-format .document-info-section { text-align: left; }
[dir="rtl"] .print-format .col-description { text-align: right; }
</style>
